// Extract unique property and unit IDs
const notifications = $input.all();
const notifData = notifications.map(n => n.json);

const unitIds = [...new Set(notifData.map(n => n.unit_id))];
const propertyIds = [...new Set(notifData.map(n => n.property_id))];

// Calculate dynamic date range: ±21 days from earliest/latest notification
const notifDates = notifData.map(n => new Date(n.start_date));
const notifEndDates = notifData.map(n => new Date(n.end_date));

const minDate = new Date(Math.min(...notifDates));
minDate.setDate(minDate.getDate() - 21); // 3 weeks before

const maxDate = new Date(Math.max(...notifEndDates));
maxDate.setDate(maxDate.getDate() + 21); // 3 weeks after

return [{
  json: {
    notifications: notifData,
    unit_ids: unitIds,
    property_ids: propertyIds,
    date_range: {
      from: minDate.toISOString().split('T')[0],
      to: maxDate.toISOString().split('T')[0]
    }
  }
}];

// Collect all data
const notifications = $node["Extract IDs & Date Range"].json.notifications;
const reservations = $node["Fetch Reservations"].all().map(n => n.json);
const availability = $node["Fetch Availability"].all().map(n => n.json);
const prices = $node["Fetch Prices"].all().map(n => n.json);
const units = $node["Fetch Units"].all().map(n => n.json);

// Calculate statistics per unit
const unitStats = {};

units.forEach(unit => {
  const unitReservations = reservations.filter(r => r.unit_id === unit.id);
  const unitAvailability = availability.filter(a => a.unit_id === unit.id);

  // Lead time calculation
  const leadTimes = unitReservations
    .filter(r => r.created_at && r.check_in)
    .map(r => {
      const created = new Date(r.created_at);
      const checkin = new Date(r.check_in);
      return Math.floor((checkin - created) / (1000 * 60 * 60 * 24));
    })
    .filter(lt => lt >= 0 && lt < 365);

  const avgLeadTime = leadTimes.length > 0
    ? Math.round(leadTimes.reduce((a, b) => a + b, 0) / leadTimes.length)
    : null;

  // Weekend vs weekday bookings
  const weekendBookings = unitReservations.filter(r => {
    const checkin = new Date(r.check_in);
    const day = checkin.getDay();
    return day === 5 || day === 6;
  }).length;

  const weekendPercentage = unitReservations.length > 0
    ? Math.round((weekendBookings / unitReservations.length) * 100)
    : null;

  // Occupancy next 30 days
  const next30Days = unitAvailability.filter(a => {
    const date = new Date(a.date);
    const diff = (date - new Date()) / (1000 * 60 * 60 * 24);
    return diff >= 0 && diff <= 30;
  });

  const bookedDays = next30Days.filter(a => a.status === 'blocked').length;
  const occupancyRate = next30Days.length > 0
    ? Math.round((bookedDays / next30Days.length) * 100)
    : null;

  // Average stay length
  const avgNights = unitReservations.length > 0
    ? Math.round(unitReservations.reduce((sum, r) => sum + (r.nights || 0), 0) / unitReservations.length)
    : null;

  unitStats[unit.id] = {
    unit_name: unit.name,
    total_bookings_6m: unitReservations.length,
    avg_lead_time_days: avgLeadTime,
    weekend_booking_percentage: weekendPercentage,
    current_occupancy_30d: occupancyRate,
    avg_stay_nights: avgNights
  };
});

// Enrich notifications with context
const enrichedNotifications = notifications.map(notif => {
  const stats = unitStats[notif.unit_id] || {};

  // Get surrounding availability (±21 days)
  const notifDate = new Date(notif.start_date);
  const before21 = new Date(notifDate);
  before21.setDate(before21.getDate() - 21);
  const after21 = new Date(notifDate);
  after21.setDate(after21.getDate() + 21);

  const surroundingAvail = availability
    .filter(a => {
      const aDate = new Date(a.date);
      return a.unit_id === notif.unit_id && aDate >= before21 && aDate <= after21;
    })
    .sort((a, b) => a.date.localeCompare(b.date))
    .map(a => `${a.date}: ${a.status}`);

  // Find gap size (consecutive available days)
  const gapStart = new Date(notif.start_date);
  const gapEnd = new Date(notif.end_date);
  const gapDays = Math.floor((gapEnd - gapStart) / (1000 * 60 * 60 * 24)) + 1;

  // Current restrictions for this date
  const currentRestrictions = prices
    .filter(p =>
      p.unit_id === notif.unit_id &&
      p.date >= notif.start_date &&
      p.date <= notif.end_date
    );

  return {
    ...notif,
    stats,
    gap_days: gapDays,
    surrounding_availability: surroundingAvail,
    current_cta: currentRestrictions[0]?.cta || 'brak',
    current_ctd: currentRestrictions[0]?.ctd || 'brak',
    current_min: currentRestrictions[0]?.min || 'brak'
  };
});

// Build Gemini prompt with new strategy
const prompt = `Jesteś ekspertem od revenue management dla wynajmu krótkoterminowego w Polsce.

ZADANIE: Zaproponuj optymalne ustawienia CTA (Close To Arrival), CTD (Close To Departure) i MIN dla ${notifications.length} powiadomień o lukach w dostępności.

KLUCZOWA STRATEGIA - MIN > CTA/CTD:
Celem NIE jest blokowanie, ale STRATEGICZNE pozwalanie na dłuższe pobyty:

1. Jednodniowa luka między rezerwacjami:
   → 1 dzień PUSTY (bez restrykcji)
   → To pozwala przedłużyć poprzednią rezerwację o 1 dzień

2. Dwudniowa luka:
   → 1 dzień pusty + 1 dzień z MIN=3
   → Nikt nie weźmie 2 dni (MIN=3), ale można przedłużyć lub wziąć 3+

3. Trzeciodniowa+ luka:
   → 1 dzień pusty
   → 2-3 dni: CTA=7-14, CTD=0, MIN=3
   → Reszta: bez restrykcji
   → Pozwala na rezerwacje 3+ dni, blokuje 1-2 dniowe

4. Przykład działania (ze screena):
   [REZ] | 1 pusty | CTA✓CTD✓MIN=3 | CTA✓CTD✓MIN=3 | puste... | [REZ]
   - Jednodniówka: NIE (MIN=3)
   - Dwudniówka: NIE (MIN=3)
   - Przedłużenie: TAK (1 pusty dzień)
   - 3+ dni: TAK (1 pusty + 2 z restrykcjami + reszta)
   - Tydzień: TAK (zabiera całą lukę)

DEFINICJE:
- CTA = ile dni przed przyjazdem przestajemy przyjmować rezerwacje
- CTD = ile dni przed wyjazdem przestajemy przyjmować rezerwacje
- MIN = minimalna długość pobytu (GŁÓWNY MECHANIZM)

DANE O POWIADOMIENIACH:
${enrichedNotifications.map((n, i) => `
${i + 1}. ${n.property_name} - ${n.unit_name}
   Luka: ${n.start_date} do ${n.end_date} (${n.gap_days} dni, ${n.change_type})
   Obecne: CTA=${n.current_cta}, CTD=${n.current_ctd}, MIN=${n.current_min}

   Statystyki:
   - Średni lead time: ${n.stats.avg_lead_time_days || 'brak'} dni
   - Weekend bookings: ${n.stats.weekend_booking_percentage || 'brak'}%
   - Obłożenie 30d: ${n.stats.current_occupancy_30d || 'brak'}%
   - Średnia długość: ${n.stats.avg_stay_nights || 'brak'} nocy
   - Rezerwacji 6m: ${n.stats.total_bookings_6m || 0}

   Otoczenie (±21 dni):
${n.surrounding_availability.slice(0, 30).join('\n')}
`).join('\n')}

ZASADY OPTYMALIZACJI:

1. GAP 1 DZIEŃ:
   → suggested_cta: 0, suggested_ctd: 0, suggested_min: 1
   → reasoning: "Pusty dzień pozwala przedłużyć poprzednią rezerwację"

2. GAP 2 DNI:
   → Dzień 1: CTA=0, CTD=0, MIN=1 (pusty)
   → Dzień 2: CTA=7-14, CTD=0, MIN=3
   → reasoning: "1 dzień pusty na przedłużenie, 2gi z MIN=3 blokuje dwudniówki"

3. GAP 3+ DNI:
   → Dzień 1: pusty (CTA=0, CTD=0, MIN=1)
   → Dni 2-3: CTA=7-14, CTD=0, MIN=3
   → Reszta: CTA=0, CTD=0, MIN=2
   → reasoning: "Strategiczne MIN=3 wypełnia luki dłuższymi pobytami"

4. WEEKEND GAP (piątek-niedziela) + >70% weekend bookings:
   → CTA=7-14, MIN=2-3 (na wszystkie dni)
   → reasoning: "Weekend premium, zachęcamy do weekendowych pobytów"

5. LOW SEASON (styczeń-marzec, listopad) + occupancy <40%:
   → CTA=0-3, MIN=2 (łagodne restrykcje)
   → reasoning: "Sezon niski, nie blokuj zbyt mocno"

6. HIGH SEASON + długi lead time (>21 dni):
   → CTA=14-21, MIN=3-5
   → reasoning: "Długi lead time pozwala czekać na dłuższe rezerwacje"

WAŻNE:
- MIN jest GŁÓWNYM narzędziem (nie CTA/CTD!)
- Zawsze pozostaw 1 pusty dzień po rezerwacji (przedłużenie)
- Nie blokuj całej luki - pozwól na dłuższe pobyty
- CTA/CTD wspierają MIN, ale MIN jest kluczowy

OUTPUT: TYLKO VALID JSON, BEZ MARKDOWN
Dla każdego dnia w luce osobny suggestion:
{
  "suggestions": [
    {
      "notification_id": "uuid",
      "unit_id": "uuid",
      "unit_name": "Domek 4D",
      "property_name": "DW Maryla",
      "date_start": "2026-06-15",
      "date_end": "2026-06-15",
      "suggested_cta": 0,
      "suggested_ctd": 0,
      "suggested_min": 1,
      "confidence": 95,
      "reasoning": "Dzień 1 luki: pusty na przedłużenie poprzedniej rezerwacji",
      "expected_impact": "Możliwość przedłużenia lub start dłuższej rezerwacji"
    },
    {
      "notification_id": "uuid",
      "unit_id": "uuid",
      "unit_name": "Domek 4D",
      "property_name": "DW Maryla",
      "date_start": "2026-06-16",
      "date_end": "2026-06-16",
      "suggested_cta": 10,
      "suggested_ctd": 0,
      "suggested_min": 3,
      "confidence": 90,
      "reasoning": "Dzień 2 luki: MIN=3 blokuje dwudniówki, CTA=10 daje czas na booking",
      "expected_impact": "Wypełnienie luki rezerwacją 3+ dni zamiast 1-2 dniowej"
    }
  ]
}`;

return [{
  json: {
    prompt,
    notifications: enrichedNotifications
  }
}];

const geminiResponse = $input.item.json;
const notifications = $node["Build Context & Prompt"].json.notifications;

// Extract JSON from Gemini response
const text = geminiResponse.candidates[0].content.parts[0].text;
let parsed;

try {
  parsed = JSON.parse(text);
} catch (e) {
  // Fallback: extract JSON from markdown
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Failed to parse Gemini response');
  }
}

// Enrich suggestions with full notification data
const enrichedSuggestions = parsed.suggestions.map(s => {
  const notif = notifications.find(n => n.id === s.notification_id);
  return {
    notification_id: s.notification_id,
    property_id: notif?.property_id,
    unit_id: s.unit_id,
    property_name: s.property_name,
    unit_name: s.unit_name,
    date_start: s.date_start,
    date_end: s.date_end,
    suggested_cta: s.suggested_cta,
    suggested_ctd: s.suggested_ctd,
    suggested_min: s.suggested_min,
    confidence: s.confidence,
    reasoning: s.reasoning,
    expected_impact: s.expected_impact,
    status: 'pending'
  };
});

return [{
  json: {
    suggestions: enrichedSuggestions
  }
}];
